<script setup>
import {computed,ref,watch} from 'vue'
const tab=ref('Inicio'),variant=ref(localStorage.getItem('nahui-variant')||'Mixto IPN'),done=ref(JSON.parse(localStorage.getItem('nahui-done')||'{}')),draft=ref(localStorage.getItem('nahui-draft')||'')
const skills=[['Lectura','R','Idea principal, detalle, inferencias y distractores.'],['Escucha','L','Información general, detalles y correcciones en audio.'],['Escritura','W','Texto de 120 a 140 palabras con registro apropiado.'],['Habla','S','Entrevista, experiencias, opinión y situaciones hipotéticas.']]
const words=computed(()=>(draft.value.trim().match(/\b[\w'-]+\b/g)||[]).length);watch(variant,v=>localStorage.setItem('nahui-variant',v));watch(draft,v=>localStorage.setItem('nahui-draft',v));function complete(s){done.value[s]=true;localStorage.setItem('nahui-done',JSON.stringify(done.value))}
</script>
<template><a class="skip" href="#main">Saltar al contenido</a><header><button class="brand" @click="tab='Inicio'"><b>4</b><span>Nahui Skills <small>BETA</small></span></button><nav><button v-for="x in ['Inicio','Lectura','Escucha','Escritura','Habla','Trampas']" :class="{active:tab===x}" @click="tab=x">{{x}}</button></nav></header><main id="main"><section v-if="tab==='Inicio'" class="hero"><div class="wrap"><span class="eyebrow">Operación rescate B2</span><h1>Cuatro habilidades.<br>Práctica sin rodeos.</h1><p>Simulador independiente, sin registro y adaptable a cualquier pantalla.</p><div class="actions"><button class="cta lime" @click="tab='Habla'">Preparar el examen oral</button><button class="cta white" @click="tab='Lectura'">Practicar las otras habilidades</button></div></div><i class="bubble b1"></i><i class="bubble b2"></i></section><section v-if="tab==='Inicio'" class="wrap section"><div class="notice"><b>Variante:</b> <select v-model="variant"><option>Mixto IPN</option><option>Inglés estadounidense</option><option>Inglés británico</option></select> Las variantes válidas no se penalizan.</div><div class="grid"><article v-for="s in skills" class="tile"><div class="tile-top"><b class="icon">{{s[1]}}</b><span>{{done[s[0]]?'100%':'0%'}}</span></div><h2>{{s[0]}}</h2><p>{{s[2]}}</p><button class="cta" @click="tab=s[0]">Practicar</button></article></div></section><section v-else class="wrap section"><button class="back" @click="tab='Inicio'">← Inicio</button><span class="eyebrow">Módulo beta</span><h1>{{tab}}</h1><article v-if="tab==='Escritura'" class="tile exercise"><h2>Consigna</h2><p>Write a formal email to correct inaccurate information on a certificate. Explain the problem, give the correct information and request a solution. Write 120–140 words.</p><textarea v-model="draft" placeholder="Write your answer here..."></textarea><p><b>{{words}}</b> palabras. Meta: 120–140.</p><button class="cta" @click="complete(tab)">Marcar terminada</button></article><article v-else-if="tab==='Habla'" class="tile exercise"><h2>Tell me about yourself, your studies and one goal for the next few years.</h2><div class="formula">Respuesta → razón → ejemplo → cierre</div><p>Habla durante 60 a 90 segundos.</p><button class="cta" @click="complete(tab)">Marcar terminada</button></article><article v-else-if="tab==='Trampas'" class="tile exercise"><h2>Método anti-trampa</h2><p><b>Most</b> no significa <b>all</b>. <b>May</b> no significa <b>will</b>. Tras <b>but</b> o <b>however</b> suele venir la corrección. <b>Not Given</b> no puede probarse ni refutarse.</p></article><article v-else class="tile exercise"><h2>{{tab==='Lectura'?'Most participants valued both formats. ¿Qué afirmación está respaldada?':'The event was planned for Monday, but it will now be held on Tuesday. ¿Cuándo será?'}}</h2><label v-for="x in ['Afirmación absoluta','Información limitada o corregida','Información no mencionada']" class="option"><input type="radio" name="q"> {{x}}</label><button class="cta" @click="complete(tab)">Calificar práctica</button></article></section></main><footer>Proyecto educativo independiente. No afiliado ni respaldado por el IPN.</footer></template>
